"""Author A1-U06 only; preserve previous sessions and lexical meanings."""
import json,copy,re,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[4]
KIT=ROOT/'plans/daily-practice-authoring'
OUT=Path(__file__).parent/'packages/A1'
PRE=Path(__file__).parent/'packages/PRE_A1'
level=json.loads((KIT/'levels/A1.plan.json').read_text())['level']
plan=level['units'][5]
W={}
for source in [OUT/'A1-U05.v1.json',OUT/'A1-U04.v1.json',OUT/'A1-U03.v1.json',OUT/'A1-U02.v1.json',OUT/'A1-U01.v1.json']+[PRE/f'PRE_A1-U{n:02}.v1.json' for n in range(20,1,-1)]+[KIT/'examples/PRE_A1-U01.v2.json']:
 for s in json.loads(source.read_text())['sessions']:
  for w in s['vocabulary']:W.setdefault(w['id'],copy.deepcopy(w))
for w in W.values():
 if 'example' not in w:w['example']=dict(fr=w['fr'],ru=w['ru'][0],transcription_ru=w['transcription_ru'])
OLD=set(W);FIRST={};S=[]
U='A1.U06.UNDERSTAND';A='A1.U06.APPLY'
OBJECTIVES={o['id']:o for u in level['units'] for o in u['objectives']}

def ru(t): return dict(text=t,text_lang='ru')

def fr(t,p): return dict(text=t,text_lang='fr',transcription_ru=p)

def ex(f,r,p): return dict(fr=f,ru=r,transcription_ru=p)

def sound(f,p): return dict(text=f,transcription_ru=p,lang='fr-FR',asset_id=None)

def wc(w): return fr(W[w]['fr'],W[w]['transcription_ru'])

def fb(g,b): return dict(correct=g,incorrect=b)

def opts(v): return [dict(id=f'c{i}',**(ru(t) if isinstance(t,str) else t)) for i,t in enumerate(v)]

def rev(i,p,cs,a,g,b): return dict(id=i,type='single_choice',instruction='Выберите один ответ.',prompt=p,choices=opts(cs),correct_choice_id=f'c{a}',feedback=fb(g,b))

def start(n,d,vs):
 p=plan['sessions'][n-1]; s={k:copy.deepcopy(p[k]) for k in ['id','title','order','kind','prerequisite_ids']}
 s.update(version=1,level='A1',unit_id=plan['id'],description=d,duration_minutes=6,objectives=copy.deepcopy(plan['objectives']),skills=[],vocabulary=[copy.deepcopy(W[w]) for w in vs],tasks=[],introductions=[]); S.append(s); return s

def base(s,sk,gs,vs,av,ins,p,g,b):
 for o in gs:
  if o not in [x['id'] for x in s['objectives']]: s['objectives'].append(copy.deepcopy(OBJECTIVES[o]))
 if sk not in s['skills']: s['skills'].append(sk)
 t=dict(id=f'Q{len(s["tasks"])+1:02}',instruction=ins,prompt=p,feedback=fb(g,b),objective_ids=gs,skill=sk,vocabulary_ids=vs,assessed_vocabulary_ids=av); s['tasks'].append(t); return t

def choose(s,sk,gs,vs,av,ins,p,cs,a,g,b):
 t=base(s,sk,gs,vs,av,ins,p,g,b); t.update(type='single_choice',choices=opts(cs),correct_choice_id=f'c{a}'); return t

def listen(s,gs,vs,av,q,f,p,cs,a,g,b):
 return choose(s,'listening',gs,vs,av,'Прослушайте и выберите ответ.',dict(**ru(q),audio=sound(f,p)),cs,a,g,b)

def intro(s,n,t,vs,ns=(),au=None):
 i=dict(id=f'I{len(s["introductions"])+1:02}',before_task_id=f'Q{n:02}',text=t,vocabulary_ids=vs)
 if ns:i['pronunciation_notes']=[dict(fr=f,transcription_ru=p) for f,p in ns]
 if au:i['audio']=sound(*au)
 s['introductions'].append(i)

def pairs(s,gs,rows,g,b):
 vs=[w for w,r in rows]; t=base(s,'vocabulary',gs,vs,vs,'Соедините каждую карточку с её значением.',ru('Используйте все карточки по одному разу.'),g,b)
 t.update(type='matching_pairs',left_items=[dict(id=f'l{i}',**wc(w)) for i,(w,r) in enumerate(rows)],right_items=[dict(id=f'r{i}',**ru(r)) for i,(w,r) in reversed(list(enumerate(rows)))],correct_pairs=[dict(left_id=f'l{i}',right_id=f'r{i}',assessed_vocabulary_ids=[w]) for i,(w,r) in enumerate(rows)])

def order(s,gs,vs,av,ins,ts,f,p,g,b):
 t=base(s,'sentence_building',gs,vs,av,ins,ru('Нажимайте на карточки в нужном порядке.'),g,b); tokens=[dict(id=f't{i}',**fr(f,p)) for i,(f,p) in enumerate(ts)]
 t.update(type='word_order',tokens=list(reversed(tokens)),accepted_orders=[[x['id'] for x in tokens]],completed_phrases=[dict(fr=f,transcription_ru=p)])

def fill(s,gs,vs,av,ins,bef,bp,aft,ap,cs,a,f,p,g,b):
 if aft=='.' and not ap:aft='';f=f.removesuffix('.');p=p.removesuffix('.')
 t=base(s,'vocabulary',gs,vs,av,ins,ru('Выберите одну карточку для пропуска.'),g,b)
 t.update(type='fill_blank',input_mode='choice',text_before=bef,text_before_transcription_ru=bp,text_after=aft,text_after_transcription_ru=ap,choices=opts(cs),correct_choice_id=f'c{a}',completed_phrases=[dict(fr=f,transcription_ru=p)])

 return t

def page(s,blocks):
 s['public_page']=dict(slug=s['id'].lower().replace('_','-'),summary=s['description'],seo_title=s['title']+' — практика французского',seo_description=s['description'],explanation_blocks=[dict(heading=h,paragraphs=ps,examples=es) for h,ps,es in blocks])

def grammar(t):
 t['skill']='grammar'
 return t

def phrase_pairs(s,gs,rows,g,b):
 vs=list(dict.fromkeys(w for f,p,r,ws,av in rows for w in ws)); avs=list(dict.fromkeys(w for f,p,r,ws,av in rows for w in av))
 t=base(s,'vocabulary',gs,vs,avs,'Соедините реплику или выражение с его смыслом.',ru('Используйте каждую карточку один раз.'),g,b)
 t.update(type='matching_pairs',left_items=[dict(id=f'l{i}',**fr(f,p)) for i,(f,p,r,ws,av) in enumerate(rows)],right_items=[dict(id=f'r{i}',**ru(r)) for i,(f,p,r,ws,av) in reversed(list(enumerate(rows)))],correct_pairs=[dict(left_id=f'l{i}',right_id=f'r{i}',assessed_vocabulary_ids=av) for i,(f,p,r,ws,av) in enumerate(rows)])
 return t

def addword(i,key,f,r,p,e,n,reviews):
 W[i]=dict(id=i,lexeme_key=key,fr=f,ru=[r],transcription_ru=p,example=e,review_items=reviews);FIRST[i]=n
addword('gare','fr:gare:railway-station','une gare','железнодорожный вокзал','юн га́р',ex('Où est la gare ?','Где вокзал?','у э ла га́р'),1,[rev('gare-meaning',fr('Une gare','юн га́р'),['Аптека','Железнодорожный вокзал','Перекрёсток'],1,'Это железнодорожный вокзал.','Нужен вокзал; аптека и перекрёсток — другие ориентиры.'),rev('gare-use',ru('Нужно спросить, где железнодорожный вокзал. Что выбрать?'),[fr('Où est la pharmacie ?','у э ла фармаси́'),fr('Où est le parc ?','у э лё па́рк'),fr('Où est la gare ?','у э ла га́р')],2,'Вопрос относится к вокзалу.','Аптека и парк меняют нужный ориентир.')])
addword('pharmacie','fr:pharmacie:pharmacy','une pharmacie','аптека','юн фармаси́',ex('La pharmacie est à côté de la gare.','Аптека рядом с вокзалом.','ла фармаси э а котэ дё ла га́р'),1,[rev('pharmacie-meaning',fr('Une pharmacie','юн фармаси́'),['Аптека','Магазин одежды','Вокзал'],0,'Это аптека.','Нужна аптека; магазин одежды и вокзал обозначают другие места.'),rev('pharmacie-use',ru('Вы хотите узнать, где аптека. Какой вопрос выбрать?'),[fr('Où est la gare ?','у э ла га́р'),fr('Où est la pharmacie ?','у э ла фармаси́'),fr('Où est le carrefour ?','у э лё карфу́р')],1,'Выбран вопрос об аптеке.','Вокзал и перекрёсток меняют место, о котором спрашивают.')])
addword('carrefour','fr:carrefour:crossroads','un carrefour','перекрёсток','э(н) карфу́р',ex('Il y a un carrefour.','Есть перекрёсток.','иль я э(н) карфу́р'),1,[rev('carrefour-meaning',fr('Un carrefour','э(н) карфу́р'),['Улица','Аптека','Перекрёсток'],2,'Назван перекрёсток.','Нужен перекрёсток, а не улица целиком или аптека.'),rev('carrefour-use',ru('Нужно сообщить о перекрёстке как ориентире. Что выбрать?'),[fr('Il y a un carrefour.','иль я э(н) карфу́р'),fr('Il y a un café.','иль я э(н) кафэ́'),fr('Il y a une gare.','иль я юн га́р')],0,'Назван нужный ориентир — перекрёсток.','Кафе и вокзал не сообщают о перекрёстке.')])
addword('pour-aller-a','fr:pour-aller-a:route-question','pour aller à','как пройти к… (рамка вопроса о маршруте)','пур алэ а́',ex('Pour aller à la gare, s’il vous plaît ?','Как пройти к вокзалу, пожалуйста?','пур алэ а ла гар, силь ву плэ́'),2,[rev('pour-aller-a-meaning',fr('Pour aller à la gare, s’il vous plaît ?','пур алэ а ла гар, силь ву плэ́'),['Просит показать цену','Спрашивает, как пройти к вокзалу','Сообщает об оплате'],1,'Это вопрос о пути к вокзалу.','Нужен маршрут, а не цена или способ оплаты.'),rev('pour-aller-a-use',ru('Нужно спросить, как пройти к аптеке. Что выбрать?'),[fr('Je voudrais un café.','жё вудрэ э(н) кафэ́'),fr('Je paie par carte.','жё пэ пар ка́рт'),fr('Pour aller à la pharmacie, s’il vous plaît ?','пур алэ а ла фармаси, силь ву плэ́')],2,'Вопрос просит маршрут к аптеке.','Заказ кофе и оплата не спрашивают дорогу.')])
addword('tourner','fr:tourner:turn-in-route','tourner','поворачивать при движении','турнэ́',ex('Tournez à gauche.','Поверните налево.','турнэ а го́ш'),3,[rev('tourner-meaning',fr('Tournez à droite.','турнэ а друа́т'),['Поверните направо','Идите прямо','Поверните налево'],0,'Это поворот направо.','Повернуть направо отличается и от прямого движения, и от поворота налево.'),rev('tourner-use',ru('Нужно указать поворот налево на перекрёстке. Что выбрать?'),[fr('Au carrefour, tournez à droite.','о карфур, турнэ а друа́т'),fr('Au carrefour, tournez à gauche.','о карфур, турнэ а го́ш'),fr('Allez tout droit.','алэ ту друа́')],1,'Указан поворот налево на перекрёстке.','Сохраните поворот и нужную сторону; прямо или направо меняют маршрут.')])
addword('tout-droit','fr:tout-droit:straight-ahead','tout droit','прямо (направление движения)','ту друа́',ex('Allez tout droit.','Идите прямо.','алэ ту друа́'),3,[rev('tout-droit-meaning',fr('Tout droit','ту друа́'),['Налево','Прямо','Направо'],1,'Нужно двигаться прямо.','Прямо означает без указанного поворота, а не налево или направо.'),rev('tout-droit-use',ru('Нужно дать указание идти прямо. Что выбрать?'),[fr('Allez tout droit.','алэ ту друа́'),fr('Tournez à gauche.','турнэ а го́ш'),fr('Tournez à droite.','турнэ а друа́т')],0,'Выбрано прямое движение.','Оба поворота меняют направление; здесь требуется прямо.')])
addword('a-gauche','fr:a-gauche:turn-left','à gauche','налево (направление поворота)','а го́ш',ex('Tournez à gauche.','Поверните налево.','турнэ а го́ш'),3,[rev('a-gauche-meaning',fr('À gauche','а го́ш'),['Прямо','Направо','Налево'],2,'Указано направление налево.','Налево отличается от прямо и направо.'),rev('a-gauche-use',ru('В маршруте требуется поворот налево. Что выбрать?'),[fr('Tournez à droite.','турнэ а друа́т'),fr('Tournez à gauche.','турнэ а го́ш'),fr('Allez tout droit.','алэ ту друа́')],1,'Сохранён нужный поворот.','Направо меняет сторону, а прямо исключает этот поворот.')])
addword('a-droite','fr:a-droite:turn-right','à droite','направо (направление поворота)','а друа́т',ex('Tournez à droite.','Поверните направо.','турнэ а друа́т'),3,[rev('a-droite-meaning',fr('À droite','а друа́т'),['Направо','Налево','Прямо'],0,'Указано направление направо.','Нужно направо, а не налево или прямо.'),rev('a-droite-use',ru('В маршруте требуется поворот направо. Что выбрать?'),[fr('Allez tout droit.','алэ ту друа́'),fr('Tournez à gauche.','турнэ а го́ш'),fr('Tournez à droite.','турнэ а друа́т')],2,'Выбран поворот направо.','Прямо и налево меняют указанное движение.')])
addword('pres-de','fr:pres-de:near-place','près de','близко к (названному месту)','прэ дё́',ex('Le parc est près de la gare.','Парк близко к вокзалу.','лё парк э прэ дё ла га́р'),4,[rev('pres-de-meaning',fr('Le parc est près de la gare.','лё парк э прэ дё ла га́р'),['Парк далеко от вокзала','Парк близко к вокзалу','Парк слева от вокзала'],1,'Парк близко к вокзалу.','Близость не означает далёкое расстояние и сама по себе не задаёт сторону.'),rev('pres-de-use',ru('Нужно сказать, что аптека близко к вокзалу. Что выбрать?'),[fr('La pharmacie est près de la gare.','ла фармаси э прэ дё ла га́р'),fr('La pharmacie est loin de la gare.','ла фармаси э луэ(н) дё ла га́р'),fr('La gare est près du parc.','ла гар э прэ дю па́рк')],0,'Сохранены аптека, близость и ориентир вокзал.','Далеко меняет расстояние, а вокзал рядом с парком сообщает о другой паре мест.')])
