page(s,[('Место и путь',['Вопрос где помогает узнать расположение. Рамка как пройти запрашивает путь. Оба вопроса сохраняют название нужного объекта.'],[ex('Où est la gare ?','Где вокзал?','у э ла га́р'),W['pour-aller-a']['example']]),('Сообщение о движении',['Знакомый глагол движения используется и в вопросе о пути. Готовое сообщение о собственном движении не заменяет вопрос собеседнику.'],[ex('Je vais à la gare.','Я иду к вокзалу.','жё вэ а ла га́р')]),('Выбранное сочетание с парком',['Перед названием парка показана объединённая форма предлога и артикля. Полная таблица всех сочетаний здесь не требуется.'],[ex('Pour aller au parc, s’il vous plaît ?','Как пройти к парку, пожалуйста?','пур алэ о парк, силь ву плэ́')])])

