page(s,[('Короткие указания',['Показаны готовые формы обращения к собеседнику. Они задают действие, а не сообщают о собственном движении.'],[W['tout-droit']['example'],W['tourner']['example']]),('Сторона и место поворота',['В маршруте важны и сторона, и ориентир поворота. На перекрёстке и у пункта назначения — разные сведения.'],[ex('Au carrefour, tournez à droite.','На перекрёстке поверните направо.','о карфур, турнэ а друа́т')]),('Положение и движение',['Справа от названного места описывает расположение. Указание повернуть направо задаёт движение. Из одного нельзя автоматически вывести другое.'],[W['a-droite']['example']])])

